import json
import re
from collections import Counter
REPLACE_NONE = "None"
def task_func(json_str):
    def process(obj):
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                if v is None:
                    continue
                v = process(v)
                if v is not None:
                    new_dict[k] = v
            return new_dict if new_dict else None
        elif isinstance(obj, list):
            new_list = []
            for item in obj:
                item = process(item)
                if item is not None:
                    new_list.append(item)
            return new_list if new_list else None
        elif isinstance(obj, str):
            if re.match(r'^[\w\.-]+@[\w\.-]+\.\w+$', obj):
                return REPLACE_NONE
            return obj
        else:
            return obj
    def collect_values(obj, counter):
        if isinstance(obj, dict):
            for v in obj.values():
                collect_values(v, counter)
        elif isinstance(obj, list):
            for item in obj:
                collect_values(item, counter)
        else:
            counter[obj] += 1
    data = json.loads(json_str)
    processed = process(data)
    counter = Counter()
    collect_values(processed, counter)
    return {"data": processed, "value_counts": counter}
